    /** @return array<string, string> */
    private static function aliases(): array
    {
        return [
            'pragmatic' => 'pragmaticplay',
            'pragmatics' => 'pragmaticplay',
            'pragmaticplaylive' => 'pragmaticplaylive',
            'egt' => 'egtdigital',
            'egtdigital' => 'egtdigital',
            'popok' => 'popokgaming',
            'popokgaming' => 'popokgaming',
            'hacksawgaming' => 'hacksaw',
            'pascal' => 'pascalgaming',
            'pascalgaming' => 'pascalgaming',
            'iconic21slots' => 'iconic21',
            'playson' => 'playson',
            '3oaks' => '3oaksgaming',
            '3oaksp' => '3oaksgaming',
            'booming' => 'boominggames',
            'nolimitcitya' => 'nolimitcity',
            'playtechlive' => 'playtechlive',
        ];
    }

    public static function normalize(string $name): string
    {
        $key = mb_strtolower(trim($name), 'UTF-8');
        $key = strtr($key, [
            'ı' => 'i', 'İ' => 'i', 'ğ' => 'g', 'Ğ' => 'g',
            'ü' => 'u', 'Ü' => 'u', 'ş' => 's', 'Ş' => 's',
            'ö' => 'o', 'Ö' => 'o', 'ç' => 'c', 'Ç' => 'c',
        ]);
        $key = preg_replace('/[^a-z0-9]+/i', '', $key) ?: '';
        $aliases = self::aliases();
        return $aliases[$key] ?? $key;
    }

    public static function svgFor(string $provider, ?string $badgeSlug = null): string
    {
        $logos = self::logos();
        foreach ([$badgeSlug ?? '', $provider] as $candidate) {
            $candidate = trim((string) $candidate);
            if ($candidate === '') {
                continue;
            }
            $key = self::normalize($candidate);
            if ($key !== '' && isset($logos[$key])) {
                return $logos[$key];
            }
        }
        return '';
    }
}
